7	import java.util.List;
8	
9	/**
10	 * 实验与席位数据访问；席位处理映射仅落库，不输出到日志。
11	 */
12	@Repository
13	public class ExperimentRepository {
14	
15	    /** 实验行。status 取值 OPEN/CLOSED；createdAt 为 Unix 毫秒 UTC。 */
16	    public record ExperimentRow(String id, int blockCount, String status, long createdAt) {
17	    }
18	
19	    /** 席位行（盲底）：treatment 为 A/B，seatNo 可直接解码，禁止出现在普通接口。 */
20	    public record SeatRow(String experimentId, int blockNo, int seatNo, String treatment) {
21	    }
22	
23	    private static final RowMapper<ExperimentRow> EXPERIMENT_MAPPER = (rs, n) -> new ExperimentRow(
24	            rs.getString("id"),
25	            rs.getInt("block_count"),
26	            rs.getString("status"),
27	            rs.getLong("created_at"));
28	
29	    private static final RowMapper<SeatRow> SEAT_MAPPER = (rs, n) -> new SeatRow(
30	            rs.getString("experiment_id"),
31	            rs.getInt("block_no"),
32	            rs.getInt("seat_no"),
33	            rs.getString("treatment"));
34	
35	    private final JdbcTemplate jdbc;
36	
37	    public ExperimentRepository(JdbcTemplate jdbc) {
38	        this.jdbc = jdbc;
39	    }
40	
41	    public void insertExperiment(ExperimentRow row) {
42	        jdbc.update("INSERT INTO experiment (id, block_count, status, created_at) VALUES (?, ?, ?, ?)",
43	                row.id(), row.blockCount(), row.status(), row.createdAt());
44	    }
45	
46	    public ExperimentRow findById(String experimentId) {
47	        List<ExperimentRow> rows = jdbc.query(
48	                "SELECT id, block_count, status, created_at FROM experiment WHERE id = ?",
49	                EXPERIMENT_MAPPER, experimentId);
50	        return rows.isEmpty() ? null : rows.get(0);
51	    }
52	
53	    /**
54	     * 行级锁定实验，串行化同实验的分配并发；事务结束时释放。
55	     */
56	    public ExperimentRow lockById(String experimentId) {
57	        List<ExperimentRow> rows = jdbc.query(
58	                "SELECT id, block_count, status, created_at FROM experiment WHERE id = ? FOR UPDATE",
59	                EXPERIMENT_MAPPER, experimentId);
60	        return rows.isEmpty() ? null : rows.get(0);
61	    }
62	
63	    /**
64	     * 关闭实验；仅 OPEN 时生效，返回受影响行数。
65	     */
66	    public int markClosed(String experimentId) {
67	        return jdbc.update("UPDATE experiment SET status = 'CLOSED' WHERE id = ? AND status = 'OPEN'",
68	                experimentId);
69	    }
70	
71	    public void insertSeat(SeatRow seat) {
72	        jdbc.update("INSERT INTO seat (experiment_id, block_no, seat_no, treatment) VALUES (?, ?, ?, ?)",
73	                seat.experimentId(), seat.blockNo(), seat.seatNo(), seat.treatment());
74	    }
75	
76	    public List<SeatRow> findSeats(String experimentId) {
77	        return jdbc.query(
78	                "SELECT experiment_id, block_no, seat_no, treatment FROM seat "
79	                        + "WHERE experiment_id = ? ORDER BY block_no, seat_no",
80	                SEAT_MAPPER, experimentId);
81	    }
